/* Sonarr / Radarr share the same roundabout icon design — only the accent
   colour differs (cyan for Sonarr, gold for Radarr). */
export function arrIcon(accent) {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200" width="100%" height="100%">
    <circle cx="100" cy="100" r="100" fill="#2B2E4A"/>
    <rect x="76" y="0"   width="48" height="70" rx="7" fill="#3D4169"/>
    <rect x="76" y="130" width="48" height="70" rx="7" fill="#3D4169"/>
    <rect x="0"   y="76" width="70" height="48" rx="7" fill="#3D4169"/>
    <rect x="130" y="76" width="70" height="48" rx="7" fill="#3D4169"/>
    <rect x="98" y="10"  width="4" height="16" rx="2" fill="${accent}" opacity="0.55"/>
    <rect x="98" y="32"  width="4" height="16" rx="2" fill="${accent}" opacity="0.55"/>
    <rect x="98" y="154" width="4" height="16" rx="2" fill="${accent}" opacity="0.55"/>
    <rect x="98" y="176" width="4" height="16" rx="2" fill="${accent}" opacity="0.55"/>
    <rect x="10"  y="98" width="16" height="4" rx="2" fill="${accent}" opacity="0.55"/>
    <rect x="32"  y="98" width="16" height="4" rx="2" fill="${accent}" opacity="0.55"/>
    <rect x="154" y="98" width="16" height="4" rx="2" fill="${accent}" opacity="0.55"/>
    <rect x="176" y="98" width="16" height="4" rx="2" fill="${accent}" opacity="0.55"/>
    <circle cx="100" cy="100" r="33" fill="${accent}"/>
  </svg>`;
}

